def G(t):
    R=[("Challenger, Gray and Christmas","Челленджер, Грей енд Крісмас"),("SAP","Ес-Ей-Пі"),("Bloomberg","Блумберг"),("dev.ua","дев юа"),("Forbes","Форбс"),
       ("DOU","Доу"),("Djinni","Джинні"),("Anthropic","Антропік"),("Claude","Клод"),("ChatGPT","Чат Джі-Пі-Ті"),("API","Ей-Пі-Ай"),
       ("Node.js","Ноуд Джей-Ес"),("PHP","Пі-Ейч-Пі"),("QA","К'ю-Ей"),("UI/UX","Ю-Ай Ю-Екс"),("IT","ай-ті")]
    for a,b in R: t=re.sub(r"(?<![\w-])"+re.escape(a)+r"(?![\w])", b, t)
    t=re.sub(r"ШІ-(\w+)", r"\1 штучного інтелекту", t)
    for a,b in [("від ШІ","від штучного інтелекту"),("з ШІ","зі штучним інтелектом"),("на ШІ","на штучний інтелект"),("у ШІ","у штучний інтелект")]: t=t.replace(a,b)
    return t.replace("ШІ","штучний інтелект")

